import sys
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from forma_a import P, armar  # noqa: E402
C=Path(__file__).resolve().parents[4]/'contenido'/'03-medio/examenes'
Q=[]
def q(sec,en,ops,l,ex,oa,pts=1):
    tipo="Varias correctas" if len(l)>1 else "Alternativas"
    cab=f"**{{n}}.** *({tipo})* " if pts==1 else f"**{{n}}.** *({tipo}, {pts} puntos)* "
    Q.append(P(sec,cab,en,ops,l,ex,oa))
M1="OA 1 (Mód. 1)"; M3="OA 3 (Mód. 1)"; N1="OA 1 (Mód. 2)"; N3="OA 3 (Mód. 2)"
SIT=lambda t,preg: f"Lee la siguiente situación:\n\n> \"{t}\"\n\n{preg}"
q("## Módulo 1: Bienestar y salud (Preguntas 1 a 12)\n\n### OA N°1 (Módulo 1) — Factores que influyen en la salud humana (Preguntas 1 a 6)\n\n","Un estudiante pasa más de seis horas diarias frente a pantallas y casi no hace actividad física. ¿Qué efecto en su salud es esperable?",
 ["*Mayor riesgo de sedentarismo, sobrepeso y problemas de sueño","Mejor condición física, porque descansa más horas al día","Ningún efecto, porque las pantallas no influyen en la salud","Solo un efecto en la vista, sin relación con el resto del cuerpo"],"a","El exceso de pantallas sin actividad física aumenta el riesgo de sedentarismo y sobrepeso, y la luz de las pantallas por la noche altera el sueño.",M1)
q("","¿Qué indican los sellos negros «ALTO EN» que aparecen en algunos alimentos en Chile?",
 ["Que el alimento es más nutritivo y recomendable que los demás","Que el alimento fue producido en Chile con ingredientes naturales","*Que el alimento supera los límites de azúcares, sodio, grasas saturadas o calorías","Que el alimento tiene más proteínas de lo que el cuerpo necesita"],"c","Por la Ley de Etiquetado de Alimentos, el sello «ALTO EN» advierte que el producto supera los límites fijados de azúcares, sodio, grasas saturadas o calorías.",M1)
q("","Según la evidencia científica disponible, ¿qué efecto tiene el uso de cigarrillos electrónicos (vapeo) en adolescentes?",
 ["Ninguno, porque el vapor es solo agua con sabor a frutas","*Expone a la nicotina, que es adictiva y afecta el desarrollo del cerebro","Mejora la capacidad pulmonar porque reemplaza al cigarrillo común","Solo tiene efectos en personas mayores de 60 años de edad"],"b","La mayoría de los cigarrillos electrónicos contiene nicotina, que es adictiva y afecta el desarrollo del cerebro, que continúa durante la adolescencia.",M1)
q("","Según la Organización Mundial de la Salud (OMS), la salud es:",
 ["La ausencia total de enfermedades en el cuerpo, comprobada con exámenes médicos","Tener un peso adecuado para la estatura y la edad, según una tabla oficial","Hacer ejercicio al menos una vez por semana y comer cinco frutas al día","*Un estado de bienestar físico, mental y social, no solo la ausencia de enfermedad"],"d","La OMS define la salud como un estado de completo bienestar físico, mental y social, y no solamente la ausencia de enfermedad.",M1)
q("","El nivel de ingresos de una familia y su acceso a atención médica son factores de salud de tipo:",
 ["Genético","Hereditario","*Socioeconómico","Infeccioso"],"c","Los ingresos y el acceso a atención médica son factores socioeconómicos: influyen en la alimentación, la vivienda y la posibilidad de prevenir y tratar enfermedades.",M1)
q("",SIT("Camila, de 16 años, duerme cinco horas por noche, toma tres bebidas energéticas al día y no realiza actividad física. Dice que se siente cansada y ansiosa.","¿Qué recomendaciones se basan en evidencia científica? Marca **todas** las correctas."),
 ["Reemplazar las horas de sueño por más bebidas energéticas para rendir mejor","Dormir entre ocho y diez horas, como se recomienda en la adolescencia","Reducir las bebidas energéticas por su alto contenido de cafeína","Incorporar actividad física regular, que mejora el ánimo y el sueño"],"bcd","Dormir lo recomendado, reducir la cafeína de las bebidas energéticas y hacer actividad física mejoran el cansancio y la ansiedad; reemplazar el sueño por energéticas los empeora.",M1,3)
q("### OA N°3 (Módulo 1) — Transmisión de agentes infecciosos y prevención (Preguntas 7 a 12)\n\n","¿Qué medidas previenen la infección por el virus del papiloma humano (VPH)?",
 ["*La vacunación contra el VPH y el uso de preservativo","Tomar antibióticos cada vez que hay un resfrío","Lavarse los dientes después de cada comida","Evitar el contacto con animales domésticos"],"a","La vacuna contra el VPH, que en Chile se aplica en el colegio, y el uso de preservativo reducen el contagio de este virus de transmisión sexual.",M3)
q("","Lavarse las manos con agua y jabón es una medida eficaz principalmente frente a:",
 ["Las enfermedades hereditarias, como el daltonismo, que pasan de padres a hijos","*Las infecciones que se transmiten por contacto, como muchas diarreas","Las enfermedades de la piel causadas por la radiación del sol en verano","Las lesiones y fracturas producidas por golpes o caídas en el colegio"],"b","Las manos transportan microorganismos de las superficies a la boca; lavarlas con agua y jabón corta la transmisión por contacto, como la de muchas diarreas.",M3)
q("","¿Por qué el uso innecesario de antibióticos es un problema de salud pública?",
 ["Porque los antibióticos curan los resfríos virales y se agotan rápido","Porque los antibióticos son caros y no se venden en farmacias","Porque los antibióticos producen enfermedades hereditarias","*Porque favorece la aparición de bacterias resistentes a esos medicamentos"],"d","Cada uso innecesario selecciona bacterias resistentes; con el tiempo, los antibióticos dejan de servir para tratar infecciones graves. Además, no sirven contra los virus.",M3)
q("","¿Qué implicancia social tiene mantener una alta cobertura de vacunación contra el sarampión en la población?",
 ["Que las personas vacunadas ya no necesitan lavarse las manos","Que el sarampión deja de existir en todo el mundo para siempre","*Que protege también a quienes no pueden vacunarse, por la inmunidad colectiva","Que solo se benefician las personas que pagan la vacuna en forma particular"],"c","Si casi toda la población está vacunada, el virus no logra circular y se protege también a quienes no pueden vacunarse, como los recién nacidos: es la inmunidad colectiva.",M3)
q("","Una página web vende un «suplemento natural que elimina todos los virus del cuerpo en tres días». ¿Qué señal indica que la información no es confiable?",
 ["Que el producto se presenta como natural y viene en un envase atractivo","*Que promete resultados absolutos sin estudios ni fuentes verificables, y busca vender","Que el sitio web tiene muchas fotos de personas sonriendo con el producto","Que el suplemento se vende por internet y no en una farmacia de barrio"],"b","Prometer curas totales sin estudios ni fuentes verificables, con un interés comercial directo, es una señal clara de desinformación sanitaria.",M3)
q("",SIT("En un curso de 30 estudiantes, 8 enfermaron de varicela en dos semanas. Todos los enfermos viajaban en el mismo furgón escolar cerrado y ninguno estaba vacunado.","¿Qué explica mejor la propagación de la enfermedad?"),
 ["*La varicela se transmite por el aire y por contacto, y el furgón cerrado facilitó el contagio entre quienes no estaban vacunados","La varicela es una enfermedad hereditaria que aparece al mismo tiempo en los niños que comparten la misma edad y el mismo curso","Los estudiantes enfermaron porque el furgón tenía la calefacción encendida durante todo el invierno y eso causa la varicela","La varicela solo se transmite por los alimentos, así que todos debieron compartir la misma colación contaminada en el furgón"],"a","La varicela es muy contagiosa por vía aérea y por contacto; un espacio cerrado y la falta de vacunación favorecieron su propagación.",M3,3)
q("## Módulo 2: Seguridad, prevención y autocuidado (Preguntas 13 a 25)\n\n### OA N°1 (Módulo 2) — Sustancias químicas de uso cotidiano (Preguntas 13 a 18)\n\n","En la etiqueta de un producto aparece un pictograma con una calavera sobre dos huesos cruzados. ¿Qué indica?",
 ["Que el producto es inflamable y puede encenderse con facilidad","Que el producto es corrosivo y puede quemar la piel","Que el producto contamina el agua y daña a los peces","*Que el producto es tóxico y puede causar una intoxicación grave"],"d","La calavera con tibias cruzadas indica toxicidad aguda: el producto puede causar una intoxicación grave o incluso la muerte.",N1)
q("","¿Por qué nunca se debe mezclar cloro (hipoclorito) con limpiadores que contienen amoníaco?",
 ["Porque la mezcla pierde su olor y ya no sirve para limpiar ninguna superficie","Porque la mezcla se congela rápidamente y daña las cañerías de la casa","*Porque la mezcla libera gases tóxicos que dañan las vías respiratorias","Porque la mezcla cambia de color y mancha la ropa y los muebles de la casa"],"c","Al mezclar cloro con amoníaco se forman gases tóxicos (cloraminas) que irritan y dañan las vías respiratorias.",N1)
q("","Una persona toma paracetamol para un dolor de cabeza y, al mismo tiempo, un antigripal que también contiene paracetamol. ¿Cuál es el riesgo?",
 ["*Superar la dosis segura de paracetamol y dañar el hígado","Que el dolor de cabeza se vuelva contagioso para su familia","Que los medicamentos se anulen y no tengan ningún efecto","Ninguno, porque los medicamentos de farmacia son siempre seguros"],"a","Sumar dos medicamentos con el mismo principio activo puede superar la dosis segura; una sobredosis de paracetamol puede dañar gravemente el hígado.",N1)
q("","Una publicación asegura que «el vinagre desinfecta igual que el cloro cualquier superficie». ¿Qué evaluación es correcta?",
 ["Es correcta: el vinagre es un ácido y por eso desinfecta exactamente igual que el cloro en cualquier superficie de la casa","*Es incorrecta: el vinagre limpia, pero su efecto contra microorganismos es limitado y no reemplaza a un desinfectante","Es correcta: todos los productos de la cocina desinfectan, porque se usan con los alimentos y no pueden ser peligrosos","Es incorrecta solo porque el vinagre tiene un olor desagradable que nadie soporta dentro de la casa durante el día"],"b","El vinagre puede limpiar, pero su acción contra bacterias y virus es limitada; para desinfectar se recomienda un desinfectante probado, como el cloro bien diluido.",N1,2)
q("",SIT("Una familia guarda bencina en botellas de bebida, sin etiqueta, en un mueble de la cocina, cerca de la estufa.","¿Qué riesgos tiene esta práctica?"),
 ["Ningún riesgo, porque la bencina está bien cerrada en una botella de plástico y nadie de la familia la abriría por error","Solo el riesgo de que la bencina pierda su olor y su poder como combustible después de varios meses guardada","*Alguien puede confundirla con una bebida e intoxicarse, y sus vapores pueden encenderse cerca de la estufa","Solo el riesgo de que la botella se ensucie por fuera con el humo y la grasa que se acumulan en la cocina"],"c","Guardar bencina en botellas de bebida puede causar intoxicaciones por confusión, sobre todo en niños, y sus vapores inflamables pueden encenderse cerca de una fuente de calor.",N1,3)
q("","Un niño pequeño bebió un producto de limpieza. ¿Qué es lo correcto hacer primero?",
 ["*Llamar a un centro de información toxicológica o a urgencia y seguir sus indicaciones","Provocarle el vómito de inmediato metiéndole los dedos en la boca para sacar todo el producto","Darle leche con aceite para que el producto se neutralice dentro del estómago","Esperar en la casa a que aparezcan síntomas antes de llamar a alguien para pedir ayuda"],"a","Hay que llamar a un centro de información toxicológica o a urgencia y seguir sus indicaciones; provocar el vómito puede quemar otra vez el esófago con productos corrosivos.",N1)
q("### OA N°3 (Módulo 2) — Riesgos naturales y antropogénicos: prevención, mitigación y adaptación (Preguntas 19 a 25)\n\n","El mensaje de alerta que llega a los celulares para avisar de un tsunami es una medida de:",
 ["Reconstrucción después del desastre","Mitigación del daño a los edificios","Recuperación de la economía local","*Alerta temprana y preparación de la población"],"d","Avisar a la población antes de que llegue la amenaza es una medida de alerta temprana: permite evacuar a tiempo y reducir las víctimas.",N3)
q("","¿Qué acción humana aumenta el riesgo de inundaciones en las ciudades?",
 ["Plantar árboles en las plazas, en los parques y en los bandejones de las avenidas","*Pavimentar grandes superficies y construir en los cauces de ríos y quebradas","Limpiar los sumideros de aguas lluvia de las calles antes de que empiece el invierno","Respetar las zonas de inundación definidas en el plan regulador del municipio"],"b","El pavimento impide que el agua se infiltre en el suelo y construir en cauces y quebradas obstruye el paso natural del agua: ambas cosas aumentan las inundaciones.",N3)
q("","En las ciudades de la costa chilena hay señales con una ola y una flecha. ¿Qué indican?",
 ["La ubicación de las playas aptas para el baño","La dirección del viento predominante en la zona","*La vía de evacuación hacia una zona segura ante un tsunami","El lugar donde se puede estacionar frente al mar"],"c","Las señales con una ola y una flecha marcan la vía de evacuación ante un tsunami: indican el camino hacia una zona segura, en altura.",N3)
q("","Una persona está en la playa cuando ocurre un sismo tan fuerte que le cuesta mantenerse en pie. ¿Por qué debe evacuar hacia una zona alta, aunque todavía no haya alerta oficial?",
 ["Porque después de todo sismo fuerte siempre ocurre un incendio en la playa","Porque las alertas oficiales en Chile nunca funcionan durante un terremoto","Porque así evita la congestión de vehículos al volver a su casa por la costanera","*Porque un sismo así puede generar un tsunami que llegue antes que cualquier aviso"],"d","Un sismo que impide mantenerse en pie puede generar un tsunami que llegue en pocos minutos: la autoevacuación inmediata a una zona alta salva vidas aunque no haya alerta.",N3,2)
q("",SIT("Una comuna tiene viviendas construidas en las laderas de los cerros y en quebradas. En los últimos inviernos, las lluvias intensas han provocado aluviones.","¿Qué medidas de mitigación y adaptación son pertinentes? Marca **todas** las correctas."),
 ["Prohibir nuevas construcciones en las quebradas","Construir obras de contención y mantener limpios los cauces","Pintar las viviendas con colores llamativos","Informar a la comunidad sobre las vías de evacuación"],"abd","Evitar construir en quebradas, construir obras de contención, limpiar los cauces e informar las vías de evacuación reducen el riesgo; el color de las viviendas no tiene relación con él.",N3,3)
q("","Una tabla muestra el origen de los incendios forestales en una temporada (datos de ejemplo, basados en los registros de CONAF):\n\n| Origen | Porcentaje |\n|---|---|\n| Accidental o por descuido (quemas, colillas, chispas) | 58 % |\n| Intencional | 38 % |\n| Natural (rayos) | 1 % |\n| Desconocido | 3 % |\n\n¿Qué se puede concluir?",
 ["Que la mayoría de los incendios forestales se producen por rayos durante las tormentas de verano","*Que casi todos los incendios tienen origen humano, por lo que la prevención depende de la conducta de las personas","Que los incendios forestales no se pueden prevenir, porque su origen es siempre desconocido","Que los incendios intencionales son más del doble de frecuentes que los accidentales"],"b","Accidental e intencional suman 96 %: casi todos los incendios los provocan las personas, así que la prevención depende sobre todo de cambiar conductas.",N3,2)
q("","Al evaluar las capacidades de un hogar frente a un incendio, ¿qué elementos son pertinentes? Marca **todas** las correctas.",
 ["Tener un extintor operativo y saber usarlo","El color de la pintura de la fachada","Conocer y mantener despejadas las salidas","Mantener el entorno libre de pasto seco y maleza"],"acd","Un extintor operativo, salidas despejadas y un entorno sin pasto seco aumentan la capacidad del hogar frente a un incendio; el color de la fachada no influye.",N3,3)
